/* Agile Orbit — Agile Coaching topic library */
(function(){
  'use strict';

  const topics={
    'stakeholder-coaching':{theme:'PEOPLE',title:'Stakeholder Coaching',icon:'🧭',understand:'Stakeholder coaching helps a team see the human system around its work: who is affected, who influences decisions, whose support matters and where expectations conflict. The goal is not to create a stakeholder spreadsheet; it is to improve the quality and timing of engagement.',coachFor:'Clearer relationships, earlier involvement and fewer late surprises.',signals:['Decisions are repeatedly revisited after meetings.','The Product Owner appears accountable but lacks real decision authority.','Important stakeholders appear only near release or review points.','Teams receive conflicting direction from multiple senior voices.'],questions:['Whose support is required for this outcome to succeed?','Who has influence but little day-to-day involvement?','Which stakeholder are we informing when we should be involving?','What decision is unclear because the decision-maker is unclear?'],moves:['Map stakeholders by stake and influence, then discuss engagement intentionally.','Separate decision-makers, advisers, users and people who only need visibility.','Bring high-impact stakeholders into discovery or refinement earlier.','Make escalation and decision paths explicit rather than relationship-dependent.'],practice:'Take one current initiative. Ask the team to name everyone who can materially help, block, decide or be affected. Then identify one relationship where earlier conversation would remove future waiting.',watch:'Do not turn stakeholder maps into labels such as “difficult stakeholder”. Coach the relationship and the system of decisions, not the personality.'},
    'psychological-safety':{theme:'PEOPLE',title:'Psychological Safety',icon:'🛡️',understand:'Psychological safety is the shared belief that speaking up with questions, concerns, mistakes or disagreement will not create interpersonal punishment. It does not mean comfort, consensus or low standards; it makes candid learning possible.',coachFor:'A team where risk, uncertainty and disagreement become visible early.',signals:['Meetings end in quick agreement but concerns appear afterwards.','Junior or quieter members rarely challenge dominant voices.','Mistakes are hidden until they become expensive.','Retrospectives produce safe, generic observations instead of real issues.'],questions:['What are people thinking but not saying?','What happens here when someone disagrees with a senior person?','When did someone last admit “I do not know” without being judged?','Which risk would be easier to raise anonymously than aloud?'],moves:['Invite dissent before asking for agreement.','Use silent writing before group discussion to reduce dominance effects.','Ask leaders to speak last when their opinion could anchor the group.','Model curiosity after bad news: “What did we learn?” before “Who caused this?”'],practice:'At the next team discussion, ask everyone to write one concern and one assumption silently first. Discuss the themes before asking for solutions.',watch:'Do not confuse psychological safety with avoiding accountability. High safety and high standards should reinforce each other.'},
    'team-effectiveness':{theme:'PEOPLE',title:'Team Effectiveness',icon:'🤝',understand:'Team effectiveness is less about collecting strong individuals and more about creating conditions for coordinated work: clarity, dependable commitments, meaningful goals, healthy interaction and shared ownership of outcomes.',coachFor:'A team that can coordinate, decide and recover without relying on a few heroes.',signals:['Work is owned by individuals rather than the team.','Commitments depend on one or two highly experienced people.','Roles are clear on paper but decisions still bounce around.','The team completes tasks but struggles to explain the shared outcome.'],questions:['What can only one person do today?','Where is ownership genuinely shared and where is it merely assigned?','What does this team need from each other to succeed this Sprint?','If one key person disappeared for two weeks, what would stop?'],moves:['Create working agreements around collaboration, decision-making and escalation.','Shift planning conversation from “my task” to the team outcome.','Use pairing or swarming on critical work to spread context.','Make purpose, priorities and decision boundaries visible.'],practice:'Pick one current goal and ask each person: “What do you need from the team to make this successful?” Turn recurring needs into explicit working agreements.',watch:'Avoid diagnosing team effectiveness from velocity alone. A fast team can still be fragile, dependent or solving the wrong problem.'},
    'communication-behaviour':{theme:'PEOPLE',title:'Communication & Behaviour',icon:'💬',understand:'People differ in pace, directness, need for detail, risk tolerance and how they process information. Behavioural models can create useful hypotheses, but coaching stays curious rather than fixing people into personality boxes.',coachFor:'Communication that adapts to context while preserving respect and clarity.',signals:['One person wants the headline while another wants evidence and detail.','Direct communication is interpreted as aggression or hesitation as resistance.','Important messages are technically sent but not understood.','The same conflict repeats because people react to style rather than intent.'],questions:['What does this person need in order to engage with the decision?','Are we arguing about content, pace, level of detail or communication style?','What assumption am I making about their behaviour?','How could we communicate the same message in a way they can use?'],moves:['Separate observed behaviour from interpretation.','Match message depth and channel to the decision being made.','Ask people how they prefer to receive challenge, feedback and detail.','Use behavioural frameworks as conversation starters, never diagnoses.'],practice:'Take one recurring communication tension. Write the observable behaviour, your interpretation and two alternative explanations. Test those explanations through a conversation.',watch:'The moment a model becomes “they are a D/C/I/S type, therefore…”, curiosity has usually stopped.'},
    'conflict-coaching':{theme:'PEOPLE',title:'Conflict Coaching',icon:'⚡',understand:'Conflict is information that goals, needs, values, interpretations or constraints differ. Healthy teams do not eliminate conflict; they make it discussable and choose a response appropriate to the situation.',coachFor:'Disagreement that improves decisions instead of becoming avoidance, politics or personal friction.',signals:['Important disagreements move to private chats after meetings.','People repeatedly compromise before the real issue is understood.','The loudest or most senior person becomes the default decision.','A technical disagreement is framed as a personality problem.'],questions:['What is each person trying to protect or achieve?','What need sits underneath the position being argued?','What would a good outcome need to preserve for both sides?','Does this conflict need collaboration, a decision, a compromise or simply clarity?'],moves:['Reframe positions into underlying interests and constraints.','Slow the discussion enough to separate facts, interpretations and preferences.','Use structured turn-taking when power or dominance affects airtime.','Make the decision rule explicit: consent, advice, authority, experiment or escalation.'],practice:'Ask each side to state the other side’s concern in a way the other person agrees is fair before proposing a solution.',watch:'Do not assume collaboration is always best. Some situations need a quick decision, a temporary compromise or deliberate accommodation.'},
    'mindset-learning':{theme:'PEOPLE',title:'Mindset & Learning Culture',icon:'🌱',understand:'A learning culture treats capability as developable and uses feedback, experimentation and reflection to improve. The coach helps move conversations from proving competence toward increasing competence.',coachFor:'Curiosity, experimentation and visible learning rather than perfection theatre.',signals:['People avoid unfamiliar work because failure will be visible.','Estimates are treated as promises rather than forecasts.','Retrospectives repeat the same action without testing whether it helped.','Leaders reward certainty even when the work is genuinely uncertain.'],questions:['What are we trying to learn, not just deliver?','What belief are we treating as fact?','What would make it safe enough to try a smaller experiment?','How will we know whether this change helped?'],moves:['Frame experiments with a hypothesis and observable evidence.','Celebrate useful learning, including when a hypothesis is disproved.','Separate performance judgment from learning conversations.','Use short feedback loops so mistakes remain small and informative.'],practice:'Convert one improvement action into: “We believe ___; if we try ___; we expect to observe ___ by ___.” Review the evidence, not the intention.',watch:'“Growth mindset” should not become pressure to endure broken systems. Some constraints need structural change, not more individual resilience.'},
    'change-fatigue':{theme:'PEOPLE',title:'Change Fatigue & Resistance',icon:'🪫',understand:'Change fatigue appears when the demand for adaptation exceeds people’s capacity to absorb it. Resistance may reflect overload, mistrust, previous failed initiatives, identity loss, incentive conflict or legitimate risk.',coachFor:'Change paced to the receiving system’s capacity, with concerns treated as data.',signals:['People respond to every new initiative with “this will pass too”.','Teams comply publicly but continue old behaviour privately.','Multiple changes compete for the same attention and learning capacity.','Leaders interpret exhaustion as lack of agility.'],questions:['What has this group already been asked to absorb?','What happened during the last change that shapes trust today?','What are people afraid they will lose?','What should we stop changing so this change has capacity to land?'],moves:['Map concurrent changes affecting the same people.','Reduce simultaneous change demand and sequence deliberately.','Acknowledge previous change history rather than pretending this starts fresh.','Invite resistors to identify risks and conditions for a workable experiment.'],practice:'List the major changes currently hitting the team. Score each by effort to absorb. Ask what can pause, combine or stop.',watch:'Do not label tired people as “resistant”. Resistance can be a rational response to accumulated change debt.'},

    'define-product':{theme:'PRODUCT',title:'Define the Product',icon:'🧭',understand:'A product is a vehicle for delivering value to known users or customers. Product coaching helps clarify the boundary: what belongs to this product, who it serves, which outcomes matter and what sits outside the team’s accountability.',coachFor:'A shared product boundary that enables coherent goals and decisions.',signals:['The backlog mixes unrelated services, projects and operational work.','Teams optimise components with no shared view of customer value.','Different leaders describe the product differently.','Success is defined by delivery milestones rather than product outcomes.'],questions:['Who receives value from this product?','What problem or need does the product exist to address?','Where does the product boundary begin and end?','What would stop being true if this product disappeared?'],moves:['Map users, customers, stakeholders and value exchanges.','Define the product boundary around value rather than organisational reporting lines.','Connect backlog items to product outcomes.','Make out-of-scope areas explicit to reduce accidental ownership.'],practice:'Ask five people independently to write one sentence beginning “This product exists to…”. Compare the answers and discuss the differences.',watch:'Do not define a product only as something sold for revenue. Internal platforms, services and capabilities can also be products when they deliver ongoing value.'},
    'product-role-clarity':{theme:'PRODUCT',title:'Product Role Clarity',icon:'👤',understand:'Role clarity is about decisions, not job titles. Product coaching helps distinguish accountability for value, strategy, discovery, delivery coordination and analysis so decisions do not disappear into committees.',coachFor:'Clear decision rights with strong collaboration and minimal hand-off ambiguity.',signals:['Several people can say no but nobody can clearly say yes.','The Product Owner maintains the backlog but cannot make priority decisions.','Project milestones override product outcomes without explicit trade-offs.','Business analysts become proxy decision-makers because real stakeholders are absent.'],questions:['Who is accountable for maximizing product value?','Which decisions require consultation and which require permission?','What decision can the Product Owner make without escalation?','Where does accountability exist without authority?'],moves:['Map recurring product decisions and name the accountable role for each.','Separate advice from approval.','Clarify escalation only for decisions outside the role’s boundary.','Bring the people with actual market, customer and strategy context into product conversations.'],practice:'Take the last five delayed decisions. For each, write who decided, who advised and how long it waited. Look for decision-right ambiguity.',watch:'Adding more role descriptions rarely fixes unclear authority. Coach the actual decision system.'},
    'outcomes-value':{theme:'PRODUCT',title:'Outputs → Outcomes → Value',icon:'🎯',understand:'Activities describe what people do; outputs describe what is produced; outcomes describe what changes for users or stakeholders; value is the benefit created. Coaching helps teams stop treating shipped features as proof of success.',coachFor:'Product conversations anchored in observable change rather than activity volume.',signals:['Success is reported as stories closed or features released.','Teams cannot explain what customer behaviour should change.','Roadmaps are lists of output commitments with no evidence plan.','More delivery does not improve the business or customer metric that matters.'],questions:['What changed for the customer because we delivered this?','What outcome are we hoping this output will create?','What evidence would tell us the feature is not working?','Are we measuring delivery effort or product impact?'],moves:['Rewrite roadmap items as outcome hypotheses.','Pair every major output with an expected behavioural or business change.','Review outcomes after release, not only completion at release.','Stop or adapt features when evidence contradicts assumptions.'],practice:'Pick one recently released feature and fill the chain: Activity → Output → Outcome → Value. If Outcome is unclear, identify what evidence is missing.',watch:'Outcome metrics can also be gamed. Keep the causal story visible rather than chasing a target in isolation.',model:['ACTIVITY','OUTPUT','OUTCOME','VALUE']},
    'product-goals-evidence':{theme:'PRODUCT',title:'Product Goals & Evidence',icon:'🏁',understand:'A Product Goal creates a longer-term direction for the product. Coaching makes the goal useful by connecting it to evidence: what would be different if we were moving toward it?',coachFor:'A product direction that guides choices and can be inspected through evidence.',signals:['The Product Goal is a solution statement or release milestone.','Teams cannot use the goal to make trade-offs.','Measures are added after work is complete.','Several initiatives compete without a shared outcome hierarchy.'],questions:['What future state are we trying to create?','What evidence would indicate movement toward that state?','Which backlog item contributes least to the current goal?','What would make us change the goal or our approach?'],moves:['Express goals as meaningful product outcomes rather than project completion.','Define leading and lagging evidence before delivery.','Use the goal as a filter for backlog and stakeholder requests.','Inspect evidence frequently enough to adapt direction.'],practice:'Take the Product Goal and ask: “If this were achieved tomorrow, what would users or the business observe?” Turn those answers into evidence candidates.',watch:'A goal that cannot influence a trade-off is probably too vague to guide product decisions.'},
    'mvp-experimentation':{theme:'PRODUCT',title:'MVP & Experimentation',icon:'🧪',understand:'An MVP is primarily a learning strategy: the smallest approach that can test an important assumption with real evidence. It is not automatically a low-quality or miniature version of the final product.',coachFor:'Earlier learning about value, usability, feasibility and viability before heavy investment.',signals:['“MVP” means building every feature badly but quickly.','Teams spend months building before exposing the core assumption.','Scope discussions focus only on effort, not uncertainty.','The experiment cannot produce a decision regardless of result.'],questions:['What is the riskiest assumption we need to learn about?','What is the cheapest credible way to test it?','What decision will this evidence enable?','What can we fake, simulate or manually provide before automating it?'],moves:['Rank assumptions by uncertainty and impact.','Design experiments around one meaningful learning question.','Define evidence and decision thresholds before running the test.','Separate temporary experiment mechanics from production architecture.'],practice:'Write: “We believe ___ for ___ users. We will know we are right when ___.” Then design the smallest test that can produce that evidence.',watch:'Do not use MVP language to justify poor quality in areas such as security, regulatory controls or customer trust.'},
    'product-discovery':{theme:'PRODUCT',title:'Product Discovery',icon:'🔍',understand:'Discovery reduces uncertainty before and during delivery. It combines customer understanding, problem framing, assumption testing and solution exploration so teams do not become efficient at building the wrong thing.',coachFor:'Continuous discovery connected to delivery, not a separate research phase.',signals:['Requirements arrive as fixed solutions with no problem context.','Customer contact happens mainly during demos after implementation.','The loudest stakeholder becomes the source of truth.','Teams debate solutions without testing assumptions.'],questions:['Whose problem are we solving?','What evidence do we have that the problem is important?','Which assumption could invalidate this idea?','What can we learn before writing production code?'],moves:['Create regular customer or user contact.','Visualise assumptions about desirability, feasibility, viability and usability.','Use prototypes or thin experiments to test risky assumptions.','Bring engineers into discovery so feasibility learning happens early.'],practice:'For one proposed feature, list the assumptions that must be true for it to create value. Mark the riskiest one and design a test.',watch:'Discovery is not a licence for endless research. It should reduce uncertainty enough to make a better next decision.'},
    'prioritisation-tradeoffs':{theme:'PRODUCT',title:'Prioritisation & Trade-offs',icon:'⚖️',understand:'Prioritisation is the discipline of making trade-offs visible. Coaching helps teams compare value, urgency, risk, learning, opportunity and capacity instead of pretending everything can be first.',coachFor:'A smaller set of explicit priorities with understood consequences.',signals:['Every stakeholder labels their request “critical”.','Backlog order changes daily without a decision principle.','Teams start work to satisfy everyone and finish little.','Priority conversations avoid discussing what will not be done.'],questions:['If we choose this, what are we choosing not to do?','What is the cost of delaying this outcome?','Which item reduces the most uncertainty or risk?','What evidence justifies this urgency?'],moves:['Use transparent criteria such as value, time criticality, risk reduction and effort.','Limit the number of active top priorities.','Make opportunity cost explicit in stakeholder conversations.','Separate sequencing decisions from permanent importance.'],practice:'Take the top ten items. Force a top three and ask what evidence makes each one deserve scarce capacity now.',watch:'A scoring framework can create false precision. Use scores to structure conversation, not replace judgment.'},
    'customer-feedback':{theme:'PRODUCT',title:'Customer & Stakeholder Feedback',icon:'📣',understand:'Feedback is only useful when it arrives early enough to influence a decision. Product coaching strengthens loops from customers, users, operations and stakeholders into ongoing product choices.',coachFor:'Frequent, decision-relevant feedback instead of ceremonial approval at the end.',signals:['Sprint Reviews are status presentations rather than product conversations.','Feedback is collected but rarely changes backlog or goals.','Only internal stakeholders see increments.','Customer learning is summarised through layers of intermediaries.'],questions:['Whose feedback could change this decision?','How quickly after release do we learn whether value appeared?','What feedback are we missing because the right user is not present?','How do we distinguish opinion from behavioural evidence?'],moves:['Invite real users or frontline representatives into feedback loops.','Show working outcomes rather than progress slides.','Capture what changed in backlog, goal or hypothesis because of feedback.','Combine qualitative feedback with product usage or outcome evidence.'],practice:'At the next review, replace “Any feedback?” with three specific questions tied to a product decision you need to make.',watch:'More feedback is not always better. Seek feedback from the people who can reveal assumptions relevant to the decision.'},

    'technical-excellence':{theme:'TECHNOLOGY',title:'Technical Excellence',icon:'🧹',understand:'Technical excellence is the capability to change software safely and sustainably. Refactoring, clean design and debt management are not side work; they shape how quickly future learning can become reliable product change.',coachFor:'Technology that becomes easier—not harder—to change as the product evolves.',signals:['Every change takes longer because developers fear touching old areas.','Technical debt is discussed only after incidents or major delays.','Refactoring is continually removed from plans because it has no visible customer feature.','Knowledge of fragile areas sits with a few people.'],questions:['Which part of the codebase makes normal change disproportionately expensive?','What technical condition is slowing product learning today?','What debt is creating recurring interest payments in rework or delay?','How could we make the cost of this debt visible to product decisions?'],moves:['Connect debt to concrete flow, quality and risk impacts.','Refactor continuously around changing areas instead of waiting for a giant cleanup.','Create explicit engineering health signals.','Pair product and engineering decisions when short-term speed creates long-term constraint.'],practice:'Choose one recurring technical pain point and quantify its last three costs: wait, rework, incidents or delivery delay. Use that evidence in prioritisation.',watch:'Do not turn technical excellence into a separate perfection goal. The purpose is safer, faster, more sustainable change.'},
    'built-in-quality':{theme:'TECHNOLOGY',title:'Built-in Quality',icon:'✅',understand:'Built-in quality means designing work so defects and unsafe changes are detected close to where they are created. Quality is a team capability supported by automation, testability and fast feedback—not a downstream gate.',coachFor:'Shorter defect feedback loops and shared ownership of quality.',signals:['Testing starts mainly after development is “complete”.','Large batches reach QA and create long queues.','Regression testing is slow enough to delay release decisions.','Teams rely on manual heroics to confirm common behaviour.'],questions:['How quickly do we learn that a change is unsafe?','Which test feedback arrives too late to influence coding decisions?','What repeated manual check should become automated?','Where does quality ownership change hands?'],moves:['Move automated checks earlier in the delivery path.','Design acceptance criteria around observable behaviour.','Use a balanced test strategy rather than automating everything at the UI.','Treat escaped defects as feedback about the system, not only individual mistakes.'],practice:'Draw the path from code change to defect detection. Mark elapsed time at each step. Target the longest feedback delay first.',watch:'A high automated-test count is not proof of quality. Tests must be trustworthy, relevant and fast enough to guide decisions.'},
    'architecture-autonomy':{theme:'TECHNOLOGY',title:'Architecture for Team Autonomy',icon:'🏗️',understand:'Architecture shapes coordination. When components are tightly coupled, teams must synchronise changes, testing and releases. Coaching helps expose where technical design creates organisational dependency and waiting.',coachFor:'Boundaries that allow teams to change, test and deploy with less coordination overhead.',signals:['A small feature requires changes across many teams.','Release calendars exist mainly because components cannot move independently.','Shared databases or libraries create constant coordination.','Teams wait for another team to test or approve routine technical changes.'],questions:['Which architecture dependency creates the most recurring waiting?','Can this team test and release its change independently?','What boundary is unclear or shared by too many teams?','Where is organisational structure mirrored in technical coupling?'],moves:['Map dependencies around real feature flow.','Clarify service ownership and interfaces.','Use contracts and automation to reduce coordination requirements.','Prioritise decoupling where dependency cost is frequent and high-impact.'],practice:'Take one recent feature and draw every team/system it touched. Circle each hand-off that added waiting. Which one could architecture remove?',watch:'Microservices do not automatically create autonomy. Poor boundaries can multiply dependencies instead of reducing them.'},
    'small-batches-ci':{theme:'TECHNOLOGY',title:'Small Batches & Continuous Integration',icon:'🔀',understand:'Smaller changes reduce uncertainty, merge complexity and recovery cost. Continuous integration is a feedback discipline: integrate frequently, validate automatically and keep the shared codebase releasable.',coachFor:'Short integration feedback loops and less work hidden on long-lived branches.',signals:['Branches live for many days or weeks.','Merge events create large stabilisation efforts.','Integration failures appear late in the Sprint.','Teams batch changes because the pipeline is slow or unreliable.'],questions:['How long can code diverge before integration risk rises sharply?','What prevents us from integrating safely every day?','Which pipeline feedback is too slow to support small batches?','What batch size are we choosing because of process rather than necessity?'],moves:['Reduce branch lifetime progressively.','Improve fast automated checks on every integration.','Break large changes behind safe interfaces or feature toggles.','Measure integration frequency and recovery, not individual commit volume.'],practice:'Select one upcoming large change and identify how it could be split into independently integratable steps that preserve behaviour.',watch:'Frequent commits without trustworthy automated feedback are not continuous integration in the useful sense.'},
    'continuous-delivery':{theme:'TECHNOLOGY',title:'Continuous Delivery & Observability',icon:'🚀',understand:'Continuous delivery is the capability to move changes safely toward production on demand. Observability closes the loop by showing how the real system behaves after release, enabling recovery and learning.',coachFor:'Low-risk releases, rapid detection and fast recovery from failure.',signals:['Releases are rare because each one is considered dangerous.','Deployment requires many manual coordination steps.','Teams cannot quickly tell whether a release harmed users.','Rollback is slower or riskier than deploying the original change.'],questions:['What makes releasing scary today?','How quickly can we detect and recover from a bad change?','Which manual gate exists because evidence is unavailable?','What production signal would help us decide whether to continue a rollout?'],moves:['Automate repeatable deployment and verification steps.','Use progressive delivery or feature controls where appropriate.','Define observable service and customer signals before release.','Practice rollback or recovery paths before an incident requires them.'],practice:'Walk through the last release from “ready” to “live”. Mark every wait, manual hand-off and uncertainty. Choose one to automate or make observable.',watch:'Continuous delivery is not reckless deployment. The point is making safe release boring and repeatable.'},
    'ai-assisted-engineering':{theme:'TECHNOLOGY',title:'AI-Assisted Engineering',icon:'🤖',understand:'AI can dramatically reduce the effort to generate code, tests, documentation and explanations. Agile Coaching looks at the whole value stream: if one step accelerates, does customer value move faster—or does the queue simply migrate to review, testing or release?',coachFor:'AI adoption measured through end-to-end flow, quality and learning rather than code volume.',signals:['Generated code volume rises while lead time does not improve.','Review queues grow faster than developer throughput.','Teams celebrate “AI productivity” without measuring customer or delivery outcomes.','More code enters the system than testing and release capacity can absorb.'],questions:['Where did the bottleneck move after introducing AI?','What became faster—and what did not?','Are we producing more value or simply more output?','What new review, security or testing load did AI create?'],moves:['Measure idea-to-production lead time, not lines generated.','Limit AI-generated WIP to what downstream review can absorb.','Strengthen automated feedback before increasing generation speed.','Use AI for learning, test generation and code understanding—not only production volume.'],practice:'Compare the delivery path before and after AI adoption. Identify which queue grew. Run one experiment aimed at the new constraint rather than increasing generation further.',watch:'AI is an amplifier. In a weak delivery system it can amplify queues, defects and instability as easily as it amplifies useful work.',model:['IDEA','CODE ↑ AI','REVIEW','TEST','INTEGRATE','DEPLOY','OBSERVE','LEARN']},
    'human-ai-quality':{theme:'TECHNOLOGY',title:'Human + AI Quality',icon:'👤🤖',understand:'AI-generated code remains team-owned code. The central coaching question is not whether AI produced it, but what evidence makes the team confident the change is correct, secure, maintainable and appropriate.',coachFor:'Clear ownership and verification standards for AI-assisted changes.',signals:['Developers merge generated code they cannot explain.','AI-created tests simply mirror the generated implementation.','Security or licensing concerns are discovered late.','Definition of Done says nothing about AI-assisted work.'],questions:['What evidence would make us trust this AI-generated change?','Who remains accountable for the behaviour in production?','Can the reviewer explain the code without relying on the model?','What data or code must never be exposed to an external AI service?'],moves:['Define approved AI use cases and data boundaries.','Require human understanding and review for consequential changes.','Use independent tests and static/security checks rather than trusting generated tests alone.','Update working agreements or Definition of Done with AI-specific verification.'],practice:'Take one AI-generated change and ask the team to list the evidence required before production. Turn repeated evidence into an explicit team standard.',watch:'Human-in-the-loop should mean meaningful judgment, not a ceremonial click after an AI agent has already made the important decision.'},
    'ai-agents-autonomy':{theme:'TECHNOLOGY',title:'AI Agents & Safe Autonomy',icon:'🦾',understand:'AI agents can move beyond suggestions to execute tools, change files, run workflows and take actions. Coaching helps teams design boundaries between delegated autonomy and decisions that require explicit human accountability.',coachFor:'Useful agent autonomy with visible permissions, evidence and recovery paths.',signals:['An agent can take actions far beyond the task it was given.','Permissions are broad because narrowing them is inconvenient.','Teams cannot reconstruct why an automated action occurred.','Human approval exists, but only after the action has effectively happened.'],questions:['What actions may this agent take without approval?','Where must a human remain accountable?','What is the smallest permission set needed?','How would we detect, stop and recover from a harmful action?'],moves:['Define action tiers: suggest, prepare, execute-with-approval, execute-autonomously.','Use least-privilege permissions and isolated environments.','Log agent actions and preserve reviewable evidence.','Design kill switches, rollback and escalation for high-impact workflows.'],practice:'Choose one proposed agent workflow. Mark every action as LOW, MEDIUM or HIGH consequence and decide the human-control point for each level.',watch:'Do not equate autonomous with efficient. Unbounded agency can turn a small reasoning error into a large operational consequence.'},
    'knowledge-dependencies':{theme:'TECHNOLOGY',title:'Knowledge & Hero Dependencies',icon:'🧠',understand:'When only one person can safely change or diagnose a critical system, the problem is larger than staffing. It is a technology and capability constraint that increases queueing, fragility and pressure on the expert.',coachFor:'Distributed technical context and resilient capability without eliminating specialist depth.',signals:['Work waits for one person to review or explain it.','Vacations or attrition create delivery risk.','Specialists become permanent bottlenecks and are interrupted constantly.','Teams avoid certain components because they are considered “someone else’s area”.'],questions:['What only one person can do today?','Which knowledge dependency creates the most waiting?','What would safe delegation require?','How could we spread context through real work instead of documentation alone?'],moves:['Pair or ensemble on high-dependency areas.','Rotate ownership of recurring maintenance or support work.','Capture architecture decisions close to the code and workflow.','Measure whether dependency decreases, not merely whether documentation increases.'],practice:'List the top five “ask X” dependencies. Pick one and pair another person through the next real change until they can perform it with light support.',watch:'Do not punish experts by forcing instant knowledge transfer on top of their normal load. Create capacity for capability building.'},

    'dependency-constraint':{theme:'PROCESS',title:'Dependency & Constraint Coaching',icon:'🔗',understand:'Dependencies are not automatically bad. Coaching makes consequential dependencies visible, understands their cost and chooses an intentional response: Control, Influence, Escalate or Accept / Manage.',coachFor:'Less surprise, less hidden waiting and clearer ownership of system constraints.',signals:['“We are waiting for…” is a recurring Daily Scrum phrase.','Blocked work causes teams to start more work and increase WIP.','The same approval, specialist or environment delays multiple Sprints.','Individual heroics repeatedly absorb an organisational problem.'],questions:['Where does work spend more time waiting than being worked on?','Which dependency has become so normal that nobody questions it?','Can the team change it, influence it, or does leadership need to act?','What recurring organisational problem is being absorbed by heroics?'],moves:['Classify dependencies: skill, architecture, process, decision, authorisation, team, vendor or environment/data.','Capture frequency, impact and typical wait time.','Use Control / Influence / Escalate / Accept-Manage to choose a response.','Run a small experiment on the top one to three constraints and review evidence.'],practice:'Take current blocked work and score Frequency × Impact × Wait. Discuss the highest-exposure dependency first and choose one response path.',watch:'The goal is not zero dependencies. The goal is to stop being repeatedly surprised by dependencies the system already knows about.',model:['SURFACE','UNDERSTAND','CLASSIFY','PRIORITISE','EXPERIMENT']},
    'flow-bottleneck':{theme:'PROCESS',title:'Flow & Bottleneck Coaching',icon:'🚦',understand:'Flow coaching looks at the movement of value through the whole system. A bottleneck is the constraint that limits overall throughput; making other areas faster can simply create a larger queue in front of it.',coachFor:'Improvement focused on the system constraint rather than local utilisation.',signals:['One workflow stage always has more work waiting than others.','Upstream teams keep producing even when downstream is overloaded.','People are busy everywhere but completed outcomes remain slow.','Management adds capacity where work is visible rather than where flow is constrained.'],questions:['Where does work accumulate?','Which step limits how much the whole system can finish?','What are we making faster that the bottleneck cannot absorb?','What would happen if we deliberately slowed upstream work?'],moves:['Visualise queues between workflow steps.','Protect the bottleneck from avoidable interruptions.','Reduce incoming WIP until downstream capacity recovers.','Improve the constraint before optimising non-constraints.'],practice:'Map one value stream and count items waiting at each stage. Ask the team which queue is persistent across time, not just today.',watch:'A bottleneck can move after improvement. Keep observing the whole system rather than permanently optimising yesterday’s constraint.'},
    'wip-queues':{theme:'PROCESS',title:'WIP & Queue Coaching',icon:'🧱',understand:'Work in progress creates queues, context switching and delayed feedback. WIP limits are not arbitrary restrictions; they create a forcing function to finish, swarm and solve blockers instead of continuously starting.',coachFor:'Lower multitasking, faster feedback and visible pressure to resolve blocked work.',signals:['Many items are “in progress” but few finish.','Blocked items remain on the board while new work starts.','People switch repeatedly between priorities.','Cycle time rises even though utilisation appears high.'],questions:['What are we starting faster than we can finish?','What would we do differently if we could not start another item?','Which blocked item should the team swarm on?','How much of our current WIP is actually waiting?'],moves:['Make WIP visible by workflow stage.','Introduce realistic limits and treat breaches as learning signals.','Swarm to finish high-value work before pulling more.','Measure aging WIP and cycle time, not individual busyness.'],practice:'For one week, track every item started and finished. Compare the ratio and discuss what caused starts to outpace finishes.',watch:'WIP limits without support for resolving blockers can feel punitive. The coaching conversation must address why work cannot finish.'},
    'empiricism-feedback':{theme:'PROCESS',title:'Empiricism & Feedback Loops',icon:'🔄',understand:'Empiricism means making decisions from what is observed now rather than relying only on plans and assumptions. Transparency enables inspection; inspection without adaptation is just reporting.',coachFor:'Short feedback loops where evidence changes decisions.',signals:['Reviews present progress but do not influence direction.','Metrics are collected but no decision changes because of them.','Plans remain fixed even when assumptions are disproved.','Problems are visible but adaptation requires distant permission.'],questions:['What have we learned since the last decision?','What evidence would cause us to adapt?','Is this information visible to the people who can act on it?','What feedback loop is too slow for the uncertainty we face?'],moves:['Define the decision each feedback loop exists to support.','Shorten the time between action, observation and adaptation.','Make important work and risk visible.','Move decision authority closer to current evidence where safe.'],practice:'Pick one recurring meeting. Write the feedback it provides and the decision it should enable. If no decision changes, redesign or remove the meeting.',watch:'Transparency without psychological safety can become surveillance. Information must enable learning, not only control.'},
    'change-transformation':{theme:'PROCESS',title:'Change & Transformation Coaching',icon:'🧭',understand:'Sustainable change is usually built through contextual experiments, evidence and local capability rather than a large prescribed rollout. Coaching helps the organisation learn its way toward better operating patterns.',coachFor:'Change owned by the system rather than dependency on a transformation programme.',signals:['A future-state model is rolled out identically across very different teams.','Success is measured by adoption of ceremonies or templates.','Teams comply while old incentives and decision structures remain unchanged.','Change champions burn out because the surrounding system does not shift.'],questions:['What problem are we trying to solve with this change?','What is the smallest slice where we can test the idea?','What system condition will pull behaviour back to the old way?','How will we know the change improved value or flow?'],moves:['Blend new practices with context instead of bulldozing.','Start with a slice, show evidence and expand deliberately.','Build internal change capability and peer champions.','Change policies, incentives and decision rights that contradict the desired behaviour.'],practice:'Choose one transformation goal. Design a 30-day experiment with one team, one measurable constraint and a review date before scaling.',watch:'Do not mistake widespread adoption for improvement. A transformation can be consistently implemented and still create little value.'},
    'resistance-change':{theme:'PROCESS',title:'Resistance to Change',icon:'🛑',understand:'Resistance can be active or passive and can come from skepticism, threatened identity, incentive conflict, distrust or legitimate concern. Coaching investigates the reason rather than treating the person as an obstacle.',coachFor:'Useful concerns surfaced early and converted into better change design.',signals:['People agree in meetings but ignore the change afterwards.','A small group actively campaigns against the initiative.','Experienced practitioners question the evidence behind the change.','Teams ask “why” and are told they simply need a better mindset.'],questions:['What is this person protecting?','What evidence would make the change credible to them?','What past experience is shaping this response?','Which concern should influence the design rather than be overcome?'],moves:['Differentiate skepticism from sabotage and fatigue from disagreement.','Listen for risk information hidden inside resistance.','Invite credible skeptics into experiment design.','Make consequences, trade-offs and non-negotiable constraints explicit.'],practice:'Choose one resistant response and write three hypotheses for why it exists. Test them through inquiry before choosing an intervention.',watch:'Do not turn resistance models into a way of categorising “bad people”. The purpose is to understand the system and choose a better conversation.'},
    'communication-decision-flow':{theme:'PROCESS',title:'Communication & Decision Flow',icon:'🗣️',understand:'Different decisions need different communication richness. Simple information can move asynchronously; ambiguous, emotional or high-stakes decisions usually need richer interaction and faster feedback.',coachFor:'Communication channels chosen intentionally and decisions that do not disappear into waiting.',signals:['Complex conflicts are handled through long email threads.','Meetings exist mainly to broadcast information that could be asynchronous.','Decisions wait because nobody knows where or how they should be made.','Teams repeat conversations because context was lost across hand-offs.'],questions:['Is this message informing, aligning, deciding or resolving conflict?','How much ambiguity is present?','What feedback do we need immediately?','Where does the decision wait after this conversation?'],moves:['Use async channels for stable information and documentation.','Use richer synchronous conversation for ambiguity, conflict and joint sense-making.','Record the decision and reasoning where affected people can find it.','Define decision owner and deadline when discussion begins.'],practice:'Audit the last five meetings and five long message threads. Which should switch channel? What decision delay would that remove?',watch:'Face-to-face is not automatically better. Match the channel to ambiguity, interaction need and accessibility.'},
    'experiment-improvement':{theme:'PROCESS',title:'Experiment-Driven Improvement',icon:'🧪',understand:'Improvement becomes more reliable when actions are treated as experiments: state what you believe, change something small, observe evidence and decide whether to keep, adapt or stop.',coachFor:'Continuous improvement based on evidence rather than recurring action lists.',signals:['Retrospectives produce many actions but few are reviewed.','Large process changes are implemented without testing assumptions.','Teams cannot say whether an improvement actually helped.','Actions describe activity rather than the expected effect.'],questions:['What do we believe is causing the problem?','What small change could test that belief?','What evidence would support or contradict it?','When will we review and decide what to do next?'],moves:['Limit improvement WIP to one or two meaningful experiments.','Write each experiment with hypothesis, action, evidence and review date.','Collect baseline information before changing the system.','Stop experiments that do not help instead of keeping them out of habit.'],practice:'Rewrite one retrospective action as: “We believe ___. We will try ___. We expect ___. We will review on ___.”',watch:'An experiment is not an excuse for random change. It needs a clear learning question and evidence that can influence the next decision.'}
  };

  const modal=document.getElementById('topicModal');
  const slideEl=document.getElementById('topicSlide');
  const titleEl=document.getElementById('topicModalTitle');
  const themeEl=document.getElementById('topicModalTheme');
  const countEl=document.getElementById('topicCount');
  const dotsEl=document.getElementById('topicDots');
  const progressEl=document.getElementById('topicProgressBar');
  const prevBtn=document.getElementById('topicPrev');
  const nextBtn=document.getElementById('topicNext');
  let activeTopic=null,index=0,lastFocus=null,touchStartX=0;

  const esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
  const list=items=>`<ul class="slide-list">${items.map(i=>`<li>${esc(i)}</li>`).join('')}</ul>`;
  const flow=items=>items&&items.length?`<div class="slide-flow">${items.map((i,n)=>`${n?'<b>→</b>':''}<span>${esc(i)}</span>`).join('')}</div>`:'';

  function makeSlides(t){
    return [
      {k:'01 · UNDERSTAND',title:`What is ${t.title}?`,html:`<p class="slide-lead">${esc(t.understand)}</p><div class="slide-callout"><strong>Coach for:</strong> ${esc(t.coachFor)}</div>${flow(t.model)}`},
      {k:'02 · RECOGNISE',title:'What might the coach observe?',html:`<p class="slide-lead">Look for recurring system signals rather than judging isolated behaviour.</p>${list(t.signals)}`},
      {k:'03 · ASK',title:'Powerful coaching questions',html:`<p class="slide-lead">Use questions to make assumptions, constraints and choices visible before offering a solution.</p>${list(t.questions)}`},
      {k:'04 · INTERVENE',title:'Possible coaching moves',html:`<p class="slide-lead">Choose the lightest intervention that helps the people involved see and improve the system themselves.</p>${list(t.moves)}`},
      {k:'05 · PRACTICE',title:'Try this with a team',html:`<div class="practice-box"><strong>Practical experiment</strong><p>${esc(t.practice)}</p></div><div class="watch-box"><strong>Watch for:</strong> ${esc(t.watch)}</div>`}
    ];
  }

  function render(){
    if(!activeTopic)return;
    const t=topics[activeTopic],slides=makeSlides(t),s=slides[index];
    themeEl.textContent=`${t.icon} ${t.theme} COACHING`;
    titleEl.textContent=t.title;
    slideEl.innerHTML=`<span class="slide-kicker">${esc(s.k)}</span><h3>${esc(s.title)}</h3>${s.html}`;
    countEl.textContent=`${index+1} / ${slides.length}`;
    progressEl.style.width=`${((index+1)/slides.length)*100}%`;
    prevBtn.disabled=index===0;
    nextBtn.textContent=index===slides.length-1?'Finish ✓':'Next →';
    dotsEl.innerHTML=slides.map((_,i)=>`<button class="topic-dot${i===index?' active':''}" type="button" data-slide="${i}" aria-label="Go to slide ${i+1}"></button>`).join('');
    dotsEl.querySelectorAll('[data-slide]').forEach(btn=>btn.addEventListener('click',()=>{index=Number(btn.dataset.slide);render()}));
    slideEl.parentElement.scrollTop=0;
  }

  function openTopic(id,trigger){
    if(!topics[id]||!modal)return;
    activeTopic=id;index=0;lastFocus=trigger||document.activeElement;
    modal.hidden=false;document.body.classList.add('topic-modal-open');render();
    requestAnimationFrame(()=>modal.querySelector('.topic-modal-close').focus());
  }
  function closeTopic(){
    if(!modal||modal.hidden)return;
    modal.hidden=true;document.body.classList.remove('topic-modal-open');activeTopic=null;
    if(lastFocus&&typeof lastFocus.focus==='function')lastFocus.focus();
  }
  function next(){
    if(!activeTopic)return;
    const last=makeSlides(topics[activeTopic]).length-1;
    if(index>=last){closeTopic();return} index++;render();
  }
  function prev(){if(index>0){index--;render()}}

  document.querySelectorAll('[data-topic]').forEach(card=>card.addEventListener('click',()=>openTopic(card.dataset.topic,card)));
  document.querySelectorAll('[data-topic-close]').forEach(btn=>btn.addEventListener('click',closeTopic));
  prevBtn&&prevBtn.addEventListener('click',prev);nextBtn&&nextBtn.addEventListener('click',next);

  document.addEventListener('keydown',e=>{
    if(!modal||modal.hidden)return;
    if(e.key==='Escape'){e.preventDefault();closeTopic()}
    else if(e.key==='ArrowRight'){e.preventDefault();next()}
    else if(e.key==='ArrowLeft'){e.preventDefault();prev()}
    else if(e.key==='Tab'){
      const focusable=[...modal.querySelectorAll('button:not(:disabled)')].filter(x=>x.offsetParent!==null);
      if(!focusable.length)return;
      const first=focusable[0],last=focusable[focusable.length-1];
      if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}
      else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}
    }
  });
  slideEl&&slideEl.addEventListener('touchstart',e=>{touchStartX=e.changedTouches[0].clientX},{passive:true});
  slideEl&&slideEl.addEventListener('touchend',e=>{const d=e.changedTouches[0].clientX-touchStartX;if(Math.abs(d)>60){d<0?next():prev()}},{passive:true});

  const subnav=document.querySelector('.coach-subnav');
  const links=subnav?[...subnav.querySelectorAll('a[href^="#"]')]:[];
  const sections=links.map(a=>document.querySelector(a.getAttribute('href'))).filter(Boolean);
  if(links.length&&sections.length&&'IntersectionObserver' in window){
    const map=new Map(links.map(a=>[a.getAttribute('href').slice(1),a]));
    const observer=new IntersectionObserver(entries=>{
      const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];
      if(!visible)return;
      links.forEach(a=>a.classList.remove('active'));
      const active=map.get(visible.target.id);
      if(active){active.classList.add('active');active.scrollIntoView({block:'nearest',inline:'nearest'})}
    },{rootMargin:'-30% 0px -58% 0px',threshold:[0,.15,.35,.55]});
    sections.forEach(section=>observer.observe(section));
  }
})();
